import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.Cq50P25D.js";var i=JSON.parse(`{"title":"Benchmarking","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/benchmarking.md","filePath":"en/deep-dive/benchmarking.md","lastUpdated":1786164232000}`),a={name:`deep-dive/benchmarking.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="benchmarking" tabindex="-1">Benchmarking <a class="header-anchor" href="#benchmarking" aria-label="Permalink to “Benchmarking”">​</a></h1><h2 id="benchmark-standards" tabindex="-1">Benchmark Standards <a class="header-anchor" href="#benchmark-standards" aria-label="Permalink to “Benchmark Standards”">​</a></h2><p>The benchmark aims to obtain reliable and reproducible sync performance and algorithmic correctness statistics between Sync Engine and other syncing plugins. The Obsidian instance must have only the benchmarked plugin installed during a benchmark. And the benchmarked plugin must use the default settings except necessary account configuration.</p><p>Each benchmark contains fixed routines and test cases as specified below, any special deviation from the test routine must be documented clearly.</p><h3 id="benchmark-signature" tabindex="-1">Benchmark Signature <a class="header-anchor" href="#benchmark-signature" aria-label="Permalink to “Benchmark Signature”">​</a></h3><p>To ensure reproducibility, each benchmark must contain following metadata:</p><ul><li>Benchmarked plugin</li><li>Obsidian version</li><li>Benchmarked plugin version</li><li>Benchmarking machine operating system (due to benchmarking script assumption, Windows is not supported)</li><li>Benchmarking machine Geekbench 7 CPU single-core score (can search from <a href="https://browser.geekbench.com/" target="_blank" rel="noreferrer">Geekbench website</a> and estimate average)</li><li>Tested remote backend type and service</li><li>Average ping delay to tested service in milliseconds (use <a href="#ping-tester">Ping Tester</a>)</li><li>Average upload and download speed of the tested service in MiB/s.</li></ul><h3 id="test-cases" tabindex="-1">Test Cases <a class="header-anchor" href="#test-cases" aria-label="Permalink to “Test Cases”">​</a></h3><p><strong>Plugin size</strong>: Obtained from the GitHub release page of the corresponding version.</p><p><strong>Startup speed</strong>:</p><p>On the benchmarking machine, kill Obsidian Electron APP completely and restart for 5 times, each time record down Obsidian settings -&gt; General -&gt; Advanced -&gt; Notify if startup takes longer than expected -&gt; Stopwatch icon -&gt; benchmarked plugin startup time in milliseconds. Then take average over the 5 records.</p><p><strong>Upload speed</strong>:</p><p>Initiate a deterministic test vault using <a href="#test-vault-bootstrapper">Test Vault Bootstrapper</a>. Turn the limit off if the benchmarked plugin has large file size limits.</p><p>Then start a non-interactive sync using the plugin, wait for it to finish, and access the plugin&#39;s built in logs / profiler to obtain total sync duration. If the plugin has no non-interactive option or profiler, take screen record and perform manual UI operations. Then trim the record to critical breakpoints and measure video length.</p><p><strong>Download speed</strong>:</p><p>Reuse the already uploaded test vault above, create a new empty vault and configure the benchmarked plugin. Perform full sync to download those files from remote and record down duration.</p><p><strong>Daily sync speed</strong></p><p>Now we should have two copies of the vault, one (original) is generated from <a href="#test-vault-bootstrapper">Test Vault Bootstrapper</a>, another one (replica) is newly downloaded from remote.</p><p>Perform deterministic sync-on-change using <a href="#operation-executor">Operation Executor</a> inside the original vault. The scripts contains 10 independent and sequential test cases covering create, modify, delete, and rename (move) operations to simulate small but frequent user edit. Each operation is gated with CLI command to continue. A sync is triggered every case in original vault first, then in replica vault. If the benchmarked plugin has &quot;Sync on change&quot; option, enabled it in original vault.</p><p>When all cases finish, calculate the max, min, and median duration of the above 10 syncs.</p><p><strong>Sync correctness</strong>:</p><p>Run <a href="#correctness-validator">Correctness Validator</a> on both original and replica vault, sum up the total count of errors appeared in each vault. This stands for the stability and reliability of the plugin.</p><h2 id="benchmarking-utilities" tabindex="-1">Benchmarking Utilities <a class="header-anchor" href="#benchmarking-utilities" aria-label="Permalink to “Benchmarking Utilities”">​</a></h2><p>The benchmarking utilities are located in <code>scripts/benchmark/</code> in this repo. It is a CLI application majorly interacting with Obsidian CLI with five modules: Test Vault Bootstrapper, Operation Executor, Correctness Validator, Speed Tester, and Ping Tester.</p><h3 id="test-vault-bootstrapper" tabindex="-1">Test Vault Bootstrapper <a class="header-anchor" href="#test-vault-bootstrapper" aria-label="Permalink to “Test Vault Bootstrapper”">​</a></h3><p>File: <code>scripts/benchmark/test-vault.ts</code></p><p>Initiate a deterministic test vault using <code>scripts/benchmark/test-vault.ts</code>. Clears the vault first, then populates the vault with a large vault simulation with randomly and deeply nested files; consists 1880 small files with sizes ranging from 50 bytes to 50 KiB, 100 medium files with sizes ranging from 500 KiB to 2 MiB, and 20 large files with sizes ranging from 15 MiB to 100 MiB.</p><h3 id="operation-executor" tabindex="-1">Operation Executor <a class="header-anchor" href="#operation-executor" aria-label="Permalink to “Operation Executor”">​</a></h3><p>File: <code>scripts/benchmark/daily-test.ts</code></p><p>Operation Executor executes defined command operations in series or in parallel, it follows a declarative syntax to iterate over an array of <code>Commands</code>:</p><div class="language-TypeScript"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">TypeScript</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaybePromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">	|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">	|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">callback</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> $</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ShellPromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MaybePromise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">void</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; };</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Commands</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Command</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Array</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Command</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&gt;;</span></span></code></pre></div><p>All commands in a sub-array inside the command array are executed concurrently.</p><p>The commands are hooked to the running Obsidian instance via executing Obsidian CLI commands:</p><ul><li><code>obsidian create path=&lt;path&gt; content=&lt;content&gt; overwrite</code></li><li><code>obsidian delete path=&lt;path&gt;</code></li><li><code>obsidian move path=&lt;path&gt; to=&lt;destination&gt;</code></li></ul><p>The Daily Test routine contains 10 test cases, executed in series to simulate small but frequent user edits. The benchmarked plugin is required to perform a sync for each test case. The duration of each sync is measured for evaluation.</p><h3 id="correctness-validator" tabindex="-1">Correctness Validator <a class="header-anchor" href="#correctness-validator" aria-label="Permalink to “Correctness Validator”">​</a></h3><p>File: <code>scripts/benchmark/validator.ts</code></p><p>The validator is used to validate the sync correctness after the set of operations executed by <a href="#operation-executor">Operation Executor</a> and following syncs. It scans a vault and validates the existence of each file and folder, missing or extra ones all marked as error. For files that are appended in the test cases, it additionally validates the size of the file.</p><p>After validation, it outputs the total count of errors, and each error with its reason.</p><h3 id="speed-tester" tabindex="-1">Speed Tester <a class="header-anchor" href="#speed-tester" aria-label="Permalink to “Speed Tester”">​</a></h3><p>File: <code>scripts/benchmark/speed-test.ts</code></p><p>The speed tester tests both upload and download speeds. It needs the benchmarker to edit <code>scripts/benchmark/speed-test.ts</code> to include necessary request endpoint and authorization headers.</p><p>When started, it launches sequential <code>PUT</code> and <code>GET</code> requests to testing uploading and downloading a generated 50 MiB test file. After tests, it launches <code>DELETE</code> request to the same URL to clean up the test file.</p><p>It computes the average upload and download speeds via 50MiB / recorded time.</p><h3 id="ping-tester" tabindex="-1">Ping Tester <a class="header-anchor" href="#ping-tester" aria-label="Permalink to “Ping Tester”">​</a></h3><p>File: <code>scripts/benchmark/ping-test.ts</code></p><p>The Ping Tester tests average HTTP ping delay when trying to connect to a URL. It launches 20 sequential HTTP <code>HEAD</code> requests toward the target and record the response delay.</p><p>After all tests, it sorts the request delays and discard the longest two and shortest two delays. The calculate the average for the rest 16 samples.</p>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};